package com.wizzadrds.theworldremembers.chronicle; import org.junit.jupiter.api.Test; import java.util.*; import static org.junit.jupiter.api.Assertions.*; class ChronicleBookTest{@Test void listsAreImmutableAndOrderedModelIsStable(){var b=new ChronicleBook(List.of(new ChronicleEntry(2,"village","migration","x"),new ChronicleEntry(1,"memory","NPC_DIED","y")),List.of("p"),List.of("r"),List.of("f"),List.of("v"));assertEquals(2,b.timeline().size());assertThrows(UnsupportedOperationException.class,()->b.people().add("x"));assertEquals("village",b.timeline().get(0).category());}}